namespace HakutaiKagami.Core.Contracts;
public sealed partial class WorldSession
{
    public CommandResult HandleSupply(EntityId id,EntityId actor,bool loading,long amount,long revision){lock(gate){if(!EntityId.IsValid(id.Value)||!FieldSupply.Enabled(state)||actor!=state.PlayerControl||amount<=0)return new(ResultCode.NotAvailable,id,state.CommitSequence,"本人の物資取扱任務ではありません");var old=state.Supply!.Moves.SingleOrDefault(m=>m.Id==id);if(old!=null)return new(old.Loading==loading&&old.Amount==amount?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,id,state.CommitSequence,"取扱済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,id,state.CommitSequence,"表示を更新してください");if(!FieldSupply.AtDepot(state))return new(ResultCode.NotAvailable,id,state.CommitSequence,"登録拠点で受渡ししてください");var sourceLot=state.ResourceLots.Single(l=>l.Id==(loading?FieldSupply.Depot:FieldSupply.Carry));long source=sourceLot.Quantity-state.Reservations.Where(v=>v.Lot==sourceLot.Id&&v.Phase is ReservationPhase.Active or ReservationPhase.PartiallyConsumed).Sum(v=>v.Amount-v.Consumed);long carry=FieldSupply.Carried(state).Quantity;if(source<amount||loading&&amount>FieldSupply.Capacity-carry)return new(ResultCode.NotAvailable,id,state.CommitSequence,"在庫または携行上限が不足しています");Change(s=>{long delta=loading?amount:-amount;s.ResourceLots=s.ResourceLots.Select(l=>l.Id==FieldSupply.Depot?l with{Quantity=l.Quantity-delta,Revision=s.CommitSequence}:l.Id==FieldSupply.Carry?l with{Quantity=l.Quantity+delta,Revision=s.CommitSequence}:l).ToArray();s.Supply=s.Supply! with{Moves=[..s.Supply.Moves,new(id,loading,amount,s.ElapsedSeconds,new(actor,LocationKind.AtSite,s.Supply.Terms.Site,null,0,0,null,null,null,null))]};});return new(ResultCode.Accepted,id,state.CommitSequence,loading?"主家の兵糧を携行分へ移しました":"携行残量を主家の在庫へ返しました");}}
}
